ruleToc.chapterUrl:
@css:a@href<js>
var href = String(result).trim();
var detail = String(book.bookUrl).split(',')[0].replace(/[?#].*$/, '').replace(/\/?$/, '/');
var origin = detail.match(/^https?:\/\/[^/]+/)[0];
var url = /^https?:\/\//i.test(href) ? href : href.indexOf('//') === 0 ? detail.split(':')[0] + ':' + href : href.charAt(0) === '/' ? origin + href : detail + href;
url + ',' + JSON.stringify({headers: {Referer: detail}});
</js>
